"""Application-facing interpreter orchestration."""

import json
from collections.abc import Iterable, Iterator

from .evaluator import evaluate
from .parser import parse
from .runtime import JsonValue


class Interpreter:
    """Compile once, then evaluate each JSON input in order."""

    def __init__(self, program: str) -> None:
        self._compiled = parse(program)

    def run(self, inputs: Iterable[JsonValue]) -> Iterator[JsonValue]:
        """Yield every output, preserving input and generator ordering."""
        for value in inputs:
            yield from evaluate(self._compiled, value)


def parse_input(line: str) -> JsonValue:
    """Decode one JSON input record."""
    return json.loads(line.lstrip("\ufeff"), parse_constant=_parse_json_constant)


def _parse_json_constant(value: str) -> float:
    """Decode jq's accepted non-standard numeric constants."""
    return {"NaN": float("nan"), "Infinity": float("inf"),
            "-Infinity": float("-inf")}[value]
"""Ordered generator evaluator boundary."""

from .ast import Array, Comma, Filter, Identity, Limit, Literal, Raise
from .errors import RuntimeError
from .runtime import JsonValue, ValueStream, identity_stream


def evaluate(program: Filter, value: JsonValue) -> ValueStream:
    """Evaluate one input as an ordered stream of output values."""
    if isinstance(program, Identity):
        yield from identity_stream(value)
        return
    if isinstance(program, Literal):
        yield program.value
        return
    if isinstance(program, Comma):
        yield from evaluate(program.left, value)
        yield from evaluate(program.right, value)
        return
    if isinstance(program, Raise):
        raise RuntimeError(program.message)
    if isinstance(program, Array):
        yield list(evaluate(program.expression, value))
        return
    if isinstance(program, Limit):
        outputs = iter(evaluate(program.expression, value))
        for _ in range(program.count):
            try:
                yield next(outputs)
            except StopIteration:
                break
        return
    raise RuntimeError("unknown compiled filter")

#!/usr/bin/env python3
"""Standalone jq executable entry point.

The interpreter package owns parsing and evaluation; this tiny launcher keeps
the application-root contract explicit and lets the file remain directly
executable without installation.
"""

from __future__ import annotations

from jq_interpreter.cli import main


def run() -> int:
    """Run the command-line interface and return its process status."""
    return main()


if __name__ == "__main__":
    raise SystemExit(run())
"""Executable boundary for ``jq -c '<program>'``."""

import argparse
import json
import math
import sys
from collections.abc import Iterator

from .diagnostics import report_compile_error, report_runtime_error
from .errors import CompileError, RuntimeError
from .interpreter import Interpreter, parse_input


def _inputs() -> Iterator[object]:
    for line in sys.stdin:
        if line.strip():
            yield parse_input(line)


def _json_output(value: object) -> object:
    """Convert jq's non-finite numbers to its JSON output representation.

    jq represents NaN and infinities as ``null`` when emitting JSON.  Doing this
    recursively also covers values nested in arrays and objects.
    """
    if isinstance(value, float) and not math.isfinite(value):
        return None
    if isinstance(value, list):
        return [_json_output(item) for item in value]
    if isinstance(value, dict):
        return {key: _json_output(item) for key, item in value.items()}
    return value


def main(argv: list[str] | None = None) -> int:
    arguments = argparse.ArgumentParser(prog="jq")
    arguments.add_argument("-c", action="store_true")
    arguments.add_argument("program")
    options = arguments.parse_args(argv)
    try:
        interpreter = Interpreter(options.program)
    except CompileError as error:
        return report_compile_error(error)
    try:
        for output in interpreter.run(_inputs()):
            print(json.dumps(_json_output(output), separators=(",", ":"), ensure_ascii=False))
    except (RuntimeError, ValueError, TypeError, json.JSONDecodeError) as error:
        return report_runtime_error(RuntimeError(str(error)))
    return 0
"""Errors crossing the interpreter's process boundary."""


class CompileError(Exception):
    """The jq program could not be parsed or statically validated."""


class RuntimeError(Exception):
    """Evaluation failed after the program was compiled."""
"""Process diagnostics and exit-code policy."""

import sys
from typing import TextIO

from .errors import CompileError, RuntimeError
from .architecture import COMPILE_EXIT, RUNTIME_EXIT


def report_compile_error(error: CompileError, stream: TextIO = sys.stderr) -> int:
    print(f"jq: compile error: {error}", file=stream)
    return COMPILE_EXIT


def report_runtime_error(error: RuntimeError, stream: TextIO = sys.stderr) -> int:
    print(f"jq: runtime error: {error}", file=stream)
    return RUNTIME_EXIT
